widget_def.init:
var root=container;
var groups=[{n:'OH',z:8,p:'hydroxyle'},{n:'NH2',z:7,p:'amine'},{n:'CH3',z:6,p:'méthyle'},{n:'H',z:1,p:'hydrogène'}];
function shuffle(a){for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1));var t=a[i];a[i]=a[j];a[j]=t;}return a;}
var current=shuffle(groups.slice());
function rank(arr){var s=arr.slice().sort(function(a,b){return b.z-a.z;});return s;}
function render(){
  root.innerHTML='<div style="background:#0d0f14;font-family:system-ui,sans-serif;padding:12px;color:#e5e7eb;display:flex;flex-direction:column;gap:10px">'
  +'<div style="font-weight:700;font-size:13px">🔬 Attribution R / S (règles CIP)</div>'
  +'<div style="background:#111827;border:1px solid rgba(58,176,158,.25);border-radius:8px;padding:10px">'
  +'<div style="font-size:11px;color:#9ca3af;margin-bottom:8px">Substituants sur le carbone asymétrique (numéro atomique Z) :</div>'
  +'<div id="rs-list">'+current.map(function(g){return '<div style="display:flex;justify-content:space-between;padding:5px 8px;margin:3px 0;background:#1f2937;border-radius:6px;font-size:12px"><span><b style="color:#3ab09e">'+g.n+'</b> ('+g.p+')</span><span style="color:#9ca3af">Z = '+g.z+'</span></div>';}).join('')+'</div>'
  +'<button id="rs-reveal" style="margin-top:8px;padding:6px 12px;border-radius:6px;border:1px solid #3ab09e;background:rgba(58,176,158,.18);color:#3ab09e;font-size:12px;cursor:pointer;width:100%">Révéler le classement CIP</button>'
  +'<button id="rs-new" style="margin-top:6px;padding:5px 12px;border-radius:6px;border:1px solid rgba(255,255,255,.15);background:#1f2937;color:#9ca3af;font-size:11px;cursor:pointer;width:100%">Nouveau jeu</button>'
  +'<div id="rs-ans"></div>'
  +'<div style="font-size:9px;color:#6b7280;margin-top:8px;line-height:1.5">Ordre de priorité : Z décroissant. Le substituant 4 (Z le plus bas) pointe vers l\'arrière. Rotation 1→2→3 : horaire = <b style="color:#3ab09e">R</b>, antihoraire = <b style="color:#3ab09e">S</b>.</div>'
  +'</div></div>';
  root.querySelector('#rs-reveal').addEventListener('click',function(){
    var r=rank(current);
    root.querySelector('#rs-ans').innerHTML='<div style="margin-top:10px;padding:8px;background:#0a1a14;border:1px solid rgba(58,176,158,.3);border-radius:6px">'
      +r.map(function(g,i){return '<div style="font-size:12px;padding:2px 0"><b style="color:#fbbf24">'+(i+1)+'.</b> '+g.n+' (Z='+g.z+')'+(i===3?' ← pointe vers l\'arrière':'')+'</div>';}).join('')
      +'</div>';
  });
  root.querySelector('#rs-new').addEventListener('click',function(){current=shuffle(groups.slice());render();});
}
render();
